contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(am <= amount);
        require(address(this).balance >= amount);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        c.Collect(am); if (__ESBMC_reverted()) return;
        assert(
            c.balances(address(this)) == balBefore - am &&
            address(c).balance == contractBalBefore - am &&
            address(this).balance == thisBalBefore + am
        );
    }
    receive() external payable {}
}

