pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 amount, uint256 am) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(am <= amount);
        vm.assume(address(this).balance >= amount);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint contractBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        try c.Collect(am) {} catch { return; }
        assertTrue(c.balances(address(this)) == balBefore - am &&
            address(c).balance == contractBalBefore - am &&
            address(this).balance == thisBalBefore + am);
    }

    function testFuzz_run(uint256 amount, uint256 am) public {
        _run(amount, am);
    }

    receive() external payable {}
}
